            <v-text-field v-model="draft.packPrice" :label="draft.byWeight ? 'Цена за указанное количество, ₽' : 'Цена одной упаковки, ₽'" inputmode="decimal" hint="Для цены за кг включите покупку на вес и укажите количество 1000 г. Пусто — цена неизвестна." persistent-hint class="mb-3" />
