<script setup lang="ts">
import { ref, computed, onMounted, watch } from 'vue'
import { useApi, type MealPlan, type CookingInfo } from '~/composables/useApi'
import { useAuthStore } from '~/stores/auth'
import { readStorage, errorMessage } from '~/utils/storage'
import { planDateLabel, localDateKey } from '~/utils/plans'
import { normalizeProductUrl, productSearchLinks, defaultPurchase, normalizePurchase, purchaseKey, purchaseSummary, purchaseText, purchaseCsv, quantityText, type IngredientRow, type PurchaseRow, type PurchaseSettings } from '~/utils/purchases'
import { purchaseDefaults, type Supply } from '~/utils/purchase-defaults'
import { dateAt, normalizeOptions, planProvisions, type TripRow, type CookingTask } from '~/utils/provisions'
const api = useApi(), auth = useAuthStore(), route = useRoute(), router = useRouter()
const plans = ref<MealPlan[]>([]), selectedId = ref<number | null>(null), cooking = ref<Record<number, CookingInfo>>({})
const historyHasMore = ref(false), historyLoading = ref(false), historyError = ref('')
let historyOffset = 0
const loading = ref(false), incomplete = ref(false), error = ref(''), storageError = ref(false)
const checked = ref<string[]>([]), settings = ref<Record<string, PurchaseSettings>>({})
const options = ref(normalizeOptions({}, localDateKey()))
const selectedPlan = computed(() => plans.value.find(plan => plan.id === selectedId.value))
const safeOptions = computed(() => normalizeOptions(options.value, localDateKey(), selectedPlan.value?.daysCount))
const schedule = computed(() => planProvisions(selectedPlan.value || { daysCount: 6, items: [] }, cooking.value, safeOptions.value, settings.value))
const shoppingTrips = computed(() => schedule.value.trips.filter(trip => trip.rows.some(row => row.buy)))
const view = ref<'list' | 'calendar'>('list'), tripDay = ref(0), calendarWeek = ref(0)
const filter = ref<'all' | 'remaining' | 'done'>('all'), copied = ref(false), copyFallback = ref(false)
const editorOpen = ref(false), editing = ref<PurchaseRow | null>(null), formError = ref('')
