const tripOptions = computed(() => [{ value: -1, title: 'Весь период · общий объём' }, ...schedule.value.trips.map(trip => ({ value: trip.day, title: `${dateLabel(trip.date)} · ${trip.rows.filter(row => row.buy).length} купить` }))])
const displayedRows = computed<PurchaseRow[]>(() => tripDay.value === -1 ? schedule.value.purchases : schedule.value.trips.find(trip => trip.day === tripDay.value)?.rows || [])
const pricedSummary = computed(() => purchaseSummary(schedule.value.purchases))
const isDone = (row: PurchaseRow) => {
  if (!row.buy) return true
  if ('checkKey' in row) return checked.value.includes((row as TripRow).checkKey)
