})
const purchaseTabs = computed(() => [{ value: 'all' as const, label: 'Все', count: displayedRows.value.length }, { value: 'remaining' as const, label: 'Купить', count: displayedRows.value.filter(row => !isDone(row)).length }, { value: 'done' as const, label: 'Готово', count: displayedRows.value.filter(isDone).length }])
const calendarDays = computed(() => Array.from({ length: Math.max(0, Math.min(7, schedule.value.days - calendarWeek.value * 7)) }, (_, i) => {
  const index = calendarWeek.value * 7 + i
