const portionShare = (task: CookingTask, key: string) => {
  const total = task.ingredients.reduce((sum, row) => sum + row.weight, 0)
  const weight = task.portions.find(p => p.key === key)?.item.shoppingSnapshot?.reduce((sum, row) => sum + row.weight, 0) || 0
