}
const keyFor = (kind: string) => auth.user ? `provisions:v2:${auth.user.id}:${selectedId.value}:${kind}` : null
const settingsKey = () => auth.user ? `purchase-settings:v1:${auth.user.id}:${selectedId.value}` : null
