function saveOptions() { options.value = safeOptions.value; calendarWeek.value = 0; tripDay.value = schedule.value.trips[0]?.day ?? -1; store(keyFor('options'), options.value) }
function toggleChecked(row: PurchaseRow) { if (!('checkKey' in row)) return; const key = (row as TripRow).checkKey; checked.value = checked.value.includes(key) ? checked.value.filter(item => item !== key) : [...checked.value, key]; store(keyFor('checked'), checked.value) }
function openTrip(day: number) { tripDay.value = day; filter.value = 'all'; view.value = 'list' }
const exportTitle = computed(() => `Покупки · меню №${selectedId.value} · ${tripDay.value === -1 ? `${dateLabel(safeOptions.value.start)} — ${dateLabel(dateAt(safeOptions.value.start, schedule.value.days - 1))}` : dateLabel(dateAt(safeOptions.value.start, tripDay.value))}`)
const exportText = computed(() => purchaseText(displayedRows.value, exportTitle.value, displayedRows.value.filter(isDone).map(row => row.key)) + `\nСвободных дней без продуктов: ${schedule.value.freeDays.length}. Свежие продукты покупайте по датам календаря.`)
const printList = () => window.print()
function setDraft(value: PurchaseSettings) { draft.value = { ...value, yield: String(value.yield), pantry: String(value.pantry), packSize: value.packSize === null ? '' : String(value.packSize), packPrice: value.packPrice === null ? '' : String(value.packPrice) }; formError.value = '' }
function edit(row: PurchaseRow) { const total = schedule.value.purchases.find(item => item.key === row.key) || row; editing.value = total; setDraft(normalizePurchase(total.source, settings.value[total.key])); editorOpen.value = true }
function resetDraft() { if (editing.value) setDraft(defaultPurchase(editing.value.source)) }
function saveEdit() {
  if (!editing.value) return
