  if (draft.value.productUrl.trim() && !value.productUrl) { formError.value = 'Укажите HTTPS-ссылку на товар без логина и пароля или оставьте поле пустым.'; return }
  if (!value.name || value.name.length > 160) { formError.value = 'Укажите название товара (до 160 символов).'; return }
  if (!Number.isFinite(value.yield) || value.yield < 0.05 || value.yield > 20) { formError.value = 'Выход должен быть числом от 0,05 до 20.'; return }
  if (!Number.isFinite(value.pantry) || value.pantry < 0 || value.pantry > 1000000) { formError.value = 'Запас должен быть числом от 0 до 1 000 000.'; return }
  if (value.packSize !== null && (!Number.isFinite(value.packSize) || value.packSize < 0.01 || value.packSize > 1000000)) { formError.value = 'Укажите положительный размер упаковки до 1 000 000 или оставьте поле пустым.'; return }
  if (editing.value.unit === 'шт.' && (!Number.isInteger(value.pantry) || value.packSize !== null && !Number.isInteger(value.packSize))) { formError.value = 'Штуки и упаковки задаются целыми числами.'; return }
  if (value.packPrice !== null && (value.packSize === null || !Number.isFinite(value.packPrice) || value.packPrice < 0 || value.packPrice > 1000000)) { formError.value = 'Для цены нужен размер упаковки. Цена — от 0 до 1 000 000 ₽.'; return }
  settings.value[editing.value.key] = value
  store(settingsKey(), settings.value)
  // Only retain checks whose date, product and required purchase still match.
  const valid = new Set(schedule.value.trips.flatMap(trip => trip.rows.map(row => row.checkKey)))
