async function copyList() { try { await navigator.clipboard.writeText(exportText.value); copied.value = true } catch { copyFallback.value = true } }
function download(format: 'txt' | 'csv') {
  const fullText = `План закупок · меню №${selectedId.value}\n${safeOptions.value.start} — ${dateAt(safeOptions.value.start, schedule.value.days - 1)}\nСвободных дней без продуктов: ${schedule.value.freeDays.length}\n\n` + schedule.value.trips.map(trip => purchaseText(trip.rows, dateLabel(trip.date), trip.rows.filter(isDone).map(row => row.key))).join('\n\n')
  const blob = new Blob([format === 'txt' ? fullText : purchaseCsv(displayedRows.value, displayedRows.value.filter(isDone).map(row => row.key))], { type: format === 'txt' ? 'text/plain;charset=utf-8' : 'text/csv;charset=utf-8' })
